package com.raiiiden.warborn.common.item;import net.minecraft.world.item.*;public class WBArmorItem extends Item{public static boolean hasVisionCapability(ItemStack s){return !s.empty&&s.allowed;}public static ItemStack getInsertedGoggles(ItemStack s){return s.goggles==null?ItemStack.EMPTY:s.goggles;}public static ItemStack getInsertedBattery(ItemStack s){return s.battery==null?ItemStack.EMPTY:s.battery;}public static void setInsertedBattery(ItemStack s,ItemStack b){s.battery=b;}public boolean isTopOpen(ItemStack s){return s.open;}}
